    "Goed. Om {0} meld ik me nog één keer.": "ठीक आहे. {0} ला मी शेवटची एकदा आठवण करून देईन.",
    "Over een uur is het al morgen. De zaak van vandaag staat nog klaar.": "एका तासाने तर उद्याचा दिवस सुरू होईल. आजचे प्रकरण अजून वाट पाहत आहे.",
