    "Nog een kort verhoor voor het slapengaan? “{0}” houdt je streak van {1} dagen heel.": "झोपण्यापूर्वी एक छोटी चौकशी? “{0}” तुमची {1} दिवसांची मालिका अबाधित ठेवेल.",
    "🔥 {0} dagen. Het vuur brandt nog; één zaak houdt het aan.": "🔥 {0} दिवस. आग अजून पेटलेली आहे; एक प्रकरण ती तेवत ठेवेल.",
    "Om middernacht sluit het dossier van vandaag. Tijd genoeg voor “{0}” en dag {1} van je streak.": "मध्यरात्री आजची फाइल बंद होईल. “{0}” आणि तुमच्या मालिकेच्या {1}व्या दिवसासाठी पुरेसा वेळ आहे.",
    "Rustig avondwerk: “{0}”. Daarmee komt je streak op {1} dagen.": "संध्याकाळचे निवांत काम: “{0}”. त्याने तुमची मालिका {1} दिवसांची होईल.",
