      "भाग I · सुगीचा उत्सव",
      "फाझेंडा बोआ एस्पेरांसा, साओ पाउलो, जून 1926. पीक घरात आले आहे आणि खळे कॉफीच्या फळांनी भरले आहे. सुगीच्या उत्सवाला कॉफीसम्राट आउगुस्तो वालादारेस येत नाहीत. ते भाजणीघरात पोत्यांच्या मधोमध पडलेले असतात.",
      "उत्सव होत नाही. वेचणारे घरी जातात, पण कांपिनासहून पोलीस येईपर्यंत पाहुणे फाझेंडावरच राहतात.",
